 var png=ImageTransfer.Png(image);string project=Path.Combine(temp,"review.captovix");CompositionProject.Save(project,png,session.Document);var load=CompositionProject.Load(project);Check(load.Document.Version==19&&ImageTransfer.Bgra(EditorRenderer.Render(image,load.Document)).SequenceEqual(rendered),"Project reload retains exact reviewed pixels and schema19");
 string sourcePath=Path.Combine(temp,"image.png");ImageTransfer.Save(image,sourcePath);media=new(){Id=Guid.NewGuid().ToString("N"),FilePath=sourcePath};var saved=DocumentStore.Load(media,image,out _);DocumentStore.Save(media,saved,image);var prior=File.ReadAllBytes(DocumentStore.EditPath(media.Id));saved.Change(d=>ElementScan.Apply(d,scan,new(0,0,320,180)));DocumentStore.Save(media,saved,image);Check(File.ReadAllBytes(DocumentStore.EditPath(media.Id)+".pre-v1.39.bak").SequenceEqual(prior),"Schema19 first save backs up exact previous sidecar");var reopened=Task.Run(()=>DocumentStore.Load(media,image,out _)).GetAwaiter().GetResult();Check(reopened.Document.Annotations.Count==1&&reopened.Document.Annotations[0].Mockup!.FromScan,"Background sidecar reopen keeps reviewed element editable");
