 Popup(baseline with{ActivatedAt=now.AddDays(-4)},null,true);Popup(baseline with{Kind="trial",IssuedAt=now,LeaseUntil=now.AddHours(24),TrialUntil=now.AddDays(12)},now.AddDays(12),false);main.Close();
