 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{StaImageWorker.Stop();if(media!=null)foreach(var suffix in new[]{"",".bak",".pre-v1.38.bak",".pre-v1.39.bak",".pre-v1.13.bak"})File.Delete(DocumentStore.EditPath(media.Id)+suffix);if(media!=null)File.Delete(DocumentStore.ThumbnailPath(media.Id));Directory.Delete(temp,true);}}
